/**
 * MaterialCommunityIcons with only the glyphs the app uses (#3843): the same
 * `createIconSet` component `@expo/vector-icons/MaterialCommunityIcons` builds,
 * over a subset font and glyph map generated by
 * `tools/assets/subset_icon_fonts.py`. `name` accepts only the names in
 * `MATERIAL_COMMUNITY_ICON_NAMES` (./iconNames.ts).
 */
import createIconSet from "@expo/vector-icons/createIconSet";

import glyphMap from "./MaterialCommunityIcons.glyphmap.json";
import type { MaterialCommunityIconName } from "./iconNames";

const MaterialCommunityIcons = createIconSet(
  glyphMap as Record<MaterialCommunityIconName, number>,
  "bc-material-community-icons",
  // eslint-disable-next-line @typescript-eslint/no-require-imports -- Metro asset: a literal require() is the font's asset id
  require("../../../assets/fonts/MaterialCommunityIcons.subset.ttf")
);

export default MaterialCommunityIcons;
